template<class T>
[[nodiscard]] static constexpr UE_FORCEINLINE_HINT auto RadiansToDegrees(T const& RadVal) -> decltype(RadVal * (180.f / UE_PI))
{
	return RadVal * (180.f / UE_PI);
}

static constexpr UE_FORCEINLINE_HINT float RadiansToDegrees(float const& RadVal) { return RadVal * (180.f / UE_PI); }
static constexpr UE_FORCEINLINE_HINT double RadiansToDegrees(double const& RadVal) { return RadVal * (180.0 / UE_DOUBLE_PI); }

	// Limit the rotation of the locked foot.

	const auto FootDeltaAngle{
		FMath::RadiansToDegrees(
			FQuat4f{FootState.LockRotationWorldSpace * FootState.TargetRotationWorldSpace.Inverse()}
			.GetTwistAngle(FVector3f::UpVector))
	};

	if (FMath::Abs(FootDeltaAngle) > Settings->FootLock.FootAngleLimit + UE_KINDA_SMALL_NUMBER)
	{
		const auto ClampedAngle{FMath::Clamp(FootDeltaAngle, -Settings->FootLock.FootAngleLimit, Settings->FootLock.FootAngleLimit)};
		const FQuat4f OffsetRotation{FVector3f::UpVector, FMath::DegreesToRadians(ClampedAngle - FootDeltaAngle)};

		FootState.LockRotationWorldSpace = FQuat{OffsetRotation} * FootState.LockRotationWorldSpace;
	}
}

pub fn constrain_foot_lock_rotation(
    lock_rotation: DQuat,
    target_rotation: DQuat,
    foot_angle_limit_degrees: f32,
) -> DQuat {
    let delta = source_foot_rotation_product(lock_rotation, target_rotation.conjugate()).as_quat();
    let twist_angle = wrap_foot_yaw(2.0 * delta.y.atan2(delta.w)).to_degrees();
    let limit = foot_angle_limit_degrees;
    if twist_angle.abs() <= limit + 1e-4 { return lock_rotation; }
    source_foot_rotation_product(
        Quat::from_rotation_y((twist_angle.clamp(-limit, limit) - twist_angle).to_radians()).as_dquat(),
        lock_rotation,
    )
}
